function buildAttendancePdfParts(employeeList, { company = {}, year = ATT_YEAR, month = ATT_MONTH, attendanceRequests = [], otRecords = [] } = {}) {
  const periodKey = monthKey(year, month);
  const daysInPeriod = daysInMonthVN(year, month);
  const standardDays = standardWorkDaysFor(year, month);
  const employeesForPdf = (employeeList || []).filter(Boolean);
  const companyName = company?.name || "CÔNG TY DOMIX";
  const pad = (value) => String(value).padStart(2, "0");
  const cleanFilename = (value) => String(value || "nhan_vien").trim().replace(/[\\/:*?"<>|]/g, "_").replace(/\s+/g, "_");
  const timeText = (value) => {
    if (!value) return "-";
    const parsed = new Date(value);
    if (Number.isNaN(parsed.getTime())) return String(value).slice(11, 16) || "-";
    return parsed.toLocaleTimeString("vi-VN", { timeZone: "Asia/Ho_Chi_Minh", hour: "2-digit", minute: "2-digit" });
  };
  const latestRequest = (employeeId, day) => {
    const dateText = `${periodKey}-${pad(day)}`;
    return [...(attendanceRequests || [])].reverse().find((request) => Number(request.employeeId) === Number(employeeId) && request.date === dateText) || null;
  };
  const todayEnd = new Date(TODAY.getFullYear(), TODAY.getMonth(), TODAY.getDate(), 23, 59, 59);

  const sheetHtml = employeesForPdf.map((employee, employeeIndex) => {
    const monthRecord = employee.attendance?.[periodKey] || {};
    const monthTimes = employee.attendanceTimes?.[periodKey] || {};
    const rows = Array.from({ length: daysInPeriod }, (_, index) => {
      const day = index + 1;
      const sunday = isSundayVN(year, month, day);
      const request = latestRequest(employee.id, day);
      const storedCode = monthRecord[day] || monthRecord[String(day)] || "";
      const approvedCode = storedCode || (request?.status === "approved" ? request.code : "") || (sunday ? "CN" : "");
      const displayCode = approvedCode || (request?.status === "pending" ? request.code : "");
      const timeMeta = monthTimes[day] || monthTimes[String(day)] || {};
      const future = new Date(year, month - 1, day, 23, 59, 59) > todayEnd;
      const value = approvedCode ? Number(ATTENDANCE_CODES[approvedCode]?.value || 0) : 0;
      const checkIn = timeText(timeMeta.checkInAt || request?.checkInAt);
      const checkOut = timeText(timeMeta.checkOutAt || request?.checkOutAt);
      const isWorkedCode = ["X", "P", "O"].includes(approvedCode);
      const missingOneTime = isWorkedCode && ((checkIn !== "-" && checkOut === "-") || (checkIn === "-" && checkOut !== "-"));
      let status = "Chưa ghi";
      let tone = "";
      if (future && !approvedCode && request?.status !== "pending") { status = "Chưa đến ngày"; tone = "future"; }
      else if (request?.status === "pending" && !storedCode) { status = "Chờ duyệt"; tone = "pending"; }
      else if (request?.status === "rejected" && !storedCode) { status = "Đã từ chối"; tone = "absence"; }
      else if (approvedCode === "CN") { status = "Nghỉ Chủ nhật"; tone = "sunday"; }
      else if (["X", "P", "L", "O"].includes(approvedCode)) { status = ATTENDANCE_CODES[approvedCode]?.label || "Đã duyệt"; tone = "work"; }
      else if (["N", "K"].includes(approvedCode)) { status = ATTENDANCE_CODES[approvedCode]?.label || "Nghỉ"; tone = "absence"; }
      if (missingOneTime) { status = `${status} · thiếu ${checkIn === "-" ? "giờ vào" : "giờ ra"}`; tone = "time-missing"; }
      return {
        day,
        date: `${pad(day)}/${pad(month)}`,
        weekday: dayNameVN(year, month, day),
        code: displayCode,
        approvedCode,
        value,
        checkIn,
        checkOut,
        status,
        tone,
        missingOneTime,
      };
    });
    const renderRow = (row) => row ? `
      <tr class="${row.tone}">
        <td class="date">${row.date}</td>
        <td class="weekday">${payslipEscape(row.weekday)}</td>
        <td class="code">${row.code ? `<span class="attendance-code">${payslipEscape(row.code)}</span>` : "-"}</td>
        <td class="workday">${row.approvedCode ? row.value.toFixed(1) : "-"}</td>
        <td class="time">${payslipEscape(row.checkIn)}</td>
        <td class="time">${payslipEscape(row.checkOut)}</td>
        <td class="status" title="${payslipEscape(row.status)}">${payslipEscape(row.status)}</td>
      </tr>` : `<tr class="empty"><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td></tr>`;
    const renderHalf = (halfRows) => `
      <table class="attendance-day-table">
        <thead><tr><th class="date">Ngày</th><th class="weekday">Thứ</th><th class="code">Mã</th><th class="workday">Công</th><th class="time">Giờ vào</th><th class="time">Giờ ra</th><th class="status">Trạng thái / kiểm soát</th></tr></thead>
        <tbody>${halfRows.map(renderRow).join("")}</tbody>
      </table>`;
    const firstHalf = rows.slice(0, 16);
    const secondHalf = rows.slice(16);
    while (secondHalf.length < 16) secondHalf.push(null);
    const codeCounts = Object.keys(ATTENDANCE_CODES).reduce((result, code) => {
      result[code] = rows.filter((row) => row.approvedCode === code).length;
      return result;
    }, {});
    const actualDays = monthlyCongFor(employee.attendance, year, month);
    const pendingCount = rows.filter((row) => row.tone === "pending").length;
    const incompleteTimeCount = rows.filter((row) => row?.missingOneTime).length;
    const approvedOtHours = (otRecords || []).filter((record) => Number(record.employeeId) === Number(employee.id)
      && record.status === "approved" && String(record.date || "").startsWith(`${periodKey}-`))
      .reduce((sum, record) => sum + (Number(record.hours) || 0), 0);
    const position = employee.position || ROLE_META[employee.roleType]?.label || "Nhân viên";
    const issueDate = new Date();

    return `
      <section class="attendance-sheet">
        <div class="attendance-header">
          <div class="attendance-company"><strong>${payslipEscape(companyName)}</strong>${company?.address ? `${payslipEscape(company.address)}<br>` : ""}${company?.taxCode ? `MST: ${payslipEscape(company.taxCode)}` : ""}</div>
          <div class="attendance-document">Mã biểu: CC-${payslipEscape(employee.id || employeeIndex + 1)}-${pad(month)}${year}<br>Đơn vị tính: ngày công / giờ</div>
        </div>
        <h1 class="attendance-title">BẢNG CHẤM CÔNG CÁ NHÂN</h1>
        <div class="attendance-period">Tháng ${pad(month)} năm ${year}</div>
        <table class="attendance-info">
          <tr><td class="label">Họ và tên</td><td class="value">${payslipEscape(employee.name || "-")}</td><td class="label">Mã nhân viên</td><td class="value">${payslipEscape(employee.id || "-")}</td><td class="label">Bộ phận</td><td class="value">${payslipEscape(employee.dept || "Chưa khai báo")}</td></tr>
          <tr><td class="label">Chức vụ</td><td class="value">${payslipEscape(position)}</td><td class="label">Công chuẩn</td><td class="value">${standardDays.toFixed(1)} công</td><td class="label">Công thực tế</td><td class="value">${actualDays.toFixed(1)} công</td></tr>
        </table>
        <div class="attendance-tables"><div class="attendance-half">${renderHalf(firstHalf)}</div><div class="attendance-half">${renderHalf(secondHalf)}</div></div>
        <div class="attendance-summary">
          <div class="attendance-summary-box">
            <div class="attendance-summary-title">Tổng hợp kỳ công</div>
            <div class="attendance-metrics">
              <span class="attendance-metric">Công thực tế: <strong>${actualDays.toFixed(1)}</strong></span>
              <span class="attendance-metric">Đủ công (X): <strong>${codeCounts.X || 0}</strong></span>
              <span class="attendance-metric">Nửa công (P): <strong>${codeCounts.P || 0}</strong></span>
              <span class="attendance-metric">Phép (N): <strong>${codeCounts.N || 0}</strong></span>
              <span class="attendance-metric">Không phép (K): <strong>${codeCounts.K || 0}</strong></span>
              <span class="attendance-metric">Lễ/Tết (L): <strong>${codeCounts.L || 0}</strong></span>
              <span class="attendance-metric">OT ngày nghỉ (O): <strong>${codeCounts.O || 0}</strong></span>
              <span class="attendance-metric">Giờ OT đã duyệt: <strong>${approvedOtHours.toFixed(1)}h</strong></span>
              <span class="attendance-metric">Chờ duyệt: <strong>${pendingCount}</strong></span>
              <span class="attendance-metric">Thiếu giờ vào/ra: <strong>${incompleteTimeCount}</strong></span>
            </div>
          </div>
          <div class="attendance-summary-box attendance-legend"><div class="attendance-summary-title">Chú giải & kiểm soát</div>X: đủ công · P: nửa công · N: nghỉ có phép không lương<br>K: nghỉ không phép · L: lễ/Tết hưởng lương · O: OT ngày nghỉ · CN: Chủ nhật<br><b>Nền vàng:</b> chờ duyệt hoặc thiếu một đầu giờ vào/ra.</div>
        </div>
        <div class="attendance-signature signature-block">
          <div class="attendance-sign-date">Ngày ${issueDate.getDate()} tháng ${issueDate.getMonth() + 1} năm ${issueDate.getFullYear()}</div>
          <table class="attendance-sign"><tr>
            <td><div class="role">Người lao động</div><div class="hint">(Ký, ghi rõ họ tên)</div><div class="space"></div><div class="name">${payslipEscape(employee.name || "")}</div></td>
            <td><div class="role">Người chấm công</div><div class="hint">(Ký, ghi rõ họ tên)</div><div class="space"></div></td>
            <td><div class="role">Người duyệt</div><div class="hint">(Ký, ghi rõ họ tên)</div><div class="space"></div></td>
          </tr></table>
        </div>
        <div class="attendance-footer"><span>Dữ liệu được xuất từ hệ thống quản trị ${payslipEscape(companyName)}. Chỉ công đã duyệt mới được tính vào lương.</span><span>Trang ${employeeIndex + 1}/${employeesForPdf.length}</span></div>
      </section>`;
  }).join("");

  const suffix = employeesForPdf.length === 1 ? cleanFilename(employeesForPdf[0]?.name) : "Tat_ca_nhan_vien";
  return { css: ATTENDANCE_PDF_CSS, body: sheetHtml, filename: `DOMIX_Cham_cong_T${pad(month)}-${year}_${suffix}` };
}

async function exportAttendancePdf(employeeList, options = {}) {
  const employeesForPdf = (employeeList || []).filter(Boolean);
  if (!employeesForPdf.length) return;
  const { css, body, filename } = buildAttendancePdfParts(employeesForPdf, options);
  await saveA4Pdf({ css, body, filename, orientation: "landscape" });
}

// Dựng NỘI DUNG phiếu lương khổ A4 cho MỘT nhân viên: liệt kê từng khoản ĐƯỢC NHẬN, từng khoản BỊ TRỪ,
// thực tế nhận + số tiền bằng chữ, STK ngân hàng nhận lương và khối Kế toán duyệt / Sếp duyệt đóng dấu.
// Trả về { css, body } để vừa render ra file PDF trực tiếp, vừa dựng được bản HTML in dự phòng.
function buildPayslipParts(row, { company = {}, period = {}, approval = null, payment = null, midMonthEntries = [], midMonthPaid = 0, statusLabel = "" } = {}) {
  const month = Number(period.month) || ATT_MONTH;
  const year = Number(period.year) || ATT_YEAR;
  const dmy = (iso) => String(iso || "").slice(0, 10).split("-").reverse().join("/");
  const num = (n) => Math.round(Number(n) || 0).toLocaleString("vi-VN");
  const money = (n) => `${num(n)}đ`;
  const isOfficial = row.contractType === "chinh_thuc";
  const isCollaborator = row.contractType === "ctv";
  const usesFlatWithholding = row.contractType === "ctv" || row.contractType === "thu_viec";
  const taxPolicy = payrollTaxPolicyFor(year, month);
  const companyName = company?.name || "Công ty Công nghệ DOMIX";
  const companyAddress = company?.address || "";
  const companyPhone = company?.phone || "";
  const companyTaxCode = company?.taxCode || "";
  const slipCode = `PL-${year}${String(month).padStart(2, "0")}-${row.id || "NV"}`;
  const createdDate = dmy(TODAY_STR);

  const probationRate = Number(row.probationRate) || 1;
  const overtimeAmount = (hours, rate) => (Number(hours) || 0) * (Number(row.otHourlyRate) || 0) * (rate / 100) * probationRate;
  const overtimeItems = [
    { label: "Làm thêm ngày thường", hours: row.otByType?.weekday, rate: 150 },
    { label: "Làm thêm ngày nghỉ hằng tuần", hours: row.otByType?.weekend, rate: 200 },
    { label: "Làm thêm ngày lễ, Tết", hours: row.otByType?.holiday, rate: 300 },
  ].filter((item) => (Number(item.hours) || 0) > 0).map((item) => ({
    label: `${item.label} (${item.rate}%)`,
    note: `${Number(item.hours).toFixed(1)} giờ × ${money(row.otHourlyRate)}/giờ × ${item.rate}%${probationRate < 1 ? ` × ${Math.round(probationRate * 100)}% thử việc` : ""}`,
    amount: overtimeAmount(item.hours, item.rate),
  }));
  if ((Number(row.nightHours) || 0) > 0 || (Number(row.nightPay) || 0) > 0) {
    overtimeItems.push({
      label: "Làm việc ban đêm",
      note: `${Number(row.nightHours || 0).toFixed(1)} giờ làm việc ban đêm`,
      amount: row.nightPay || 0,
    });
  }

  const salaryItems = [
    {
      label: row.usesRevenueModel ? "Lương chính theo cơ chế doanh thu" : "Lương theo ngày công",
      note: row.usesRevenueModel
        ? (row.compStatusLabel || `Theo cơ chế lương của vị trí ${row.position || "nhân viên"}`)
        : `${money(row.daySalary)}/ngày × ${Number(row.actualDays || 0).toFixed(1)} công${probationRate < 1 ? ` × ${Math.round(probationRate * 100)}% thử việc` : ""}`,
      amount: row.mainSalary || 0,
    },
  ];
  const bonusItems = [
    { label: "Hoa hồng doanh số", note: row.compStatusLabel || "Theo doanh số được ghi nhận trong kỳ", amount: row.commission || 0 },
    { label: "Thưởng doanh số", note: "Theo chính sách thưởng của vị trí", amount: row.compBonus || 0 },
    { label: "Hoa hồng upsale kỹ thuật (7%)", note: "7% giá trị upsale đủ điều kiện", amount: row.techUpsale || 0 },
    { label: "Thưởng KPI", note: row.bonusTarget ? `${Number(row.kpi || 0)}% × mức thưởng mục tiêu ${money(row.bonusTarget)}` : "Theo kết quả KPI được duyệt", amount: row.kpiBonus || 0 },
    { label: "Thưởng mốc doanh số", note: row.kpiMilestonePct ? `${row.kpiMilestonePct}% × doanh thu tính thưởng ${money(row.kpiMilestoneNetRevenue || row.revenueUsed)}` : "", amount: row.kpiMilestoneBonus || 0 },
    { label: "Thưởng khác", note: "Khoản thưởng khác được duyệt trong kỳ", amount: row.otherBonus || 0 },
  ].filter((item) => (Number(item.amount) || 0) > 0);

  // Tiền tăng ca nằm trong nhóm PHỤ CẤP (đúng như Bảng lương tổng quát) để ô tổng "Phụ cấp"
  // trên phiếu cộng đúng bằng các dòng đang liệt kê ngay bên trên.
  const allowanceItems = [
    {
      label: "Phụ cấp ăn trưa",
      note: `Mức tháng ${money(row.configuredMealAllowance)}; ${money(row.mealAllowancePerDay)}/ngày đủ công × ${row.fullWorkDays || 0} ngày`,
      amount: row.mealAllowance || 0,
    },
    {
      label: "Phụ cấp thâm niên",
      note: `Thâm niên ${Number(row.months || 0)} tháng`,
      amount: row.seniorityAllowance || 0,
    },
    {
      label: "Phụ cấp chuyên cần",
      note: row.attendanceBonusEligible
        ? `Đủ ${Number(row.attendanceBonusWorkDays || row.standardDays).toFixed(1)}/${row.standardDays} công chuẩn`
        : `Không hưởng - mới đạt ${Number(row.attendanceBonusWorkDays || 0).toFixed(1)}/${row.standardDays} công chuẩn; thiếu ${Number(row.attendanceBonusMissingDays || 0).toFixed(1)} công`,
      amount: row.attendanceBonus || 0,
      always: true,
    },
    ...(Array.isArray(row.customAllowances) ? row.customAllowances : []).map((item) => ({
      label: item.label || "Phụ cấp khác",
      note: [
        item.prorate
          ? `Mức đăng ký ${money(item.configured)}; chia theo ${Number(row.actualDays || 0).toFixed(1)}/${row.standardDays} công`
          : `Mức áp dụng ${money(item.configured)}`,
        item.deducted > 0 ? `giảm theo ngày công ${money(item.deducted)}` : "",
        item.note || "",
      ].filter(Boolean).join("; "),
      amount: item.amount || 0,
    })),
    ...overtimeItems,
  ];

  const employeeInsuranceItems = !isOfficial
    ? [{
      label: "Bảo hiểm người lao động",
      note: isCollaborator
        ? "Cộng tác viên - không thuộc cơ chế BH bắt buộc của bảng lương này"
        : "Thử việc theo hợp đồng thử việc riêng - chưa phát sinh BH bắt buộc",
      amount: 0,
      always: true,
    }]
    : row.insuranceFixed
      ? [{
        label: "Bảo hiểm người lao động đóng",
        note: `Mức cố định theo hồ sơ; lương cơ bản ${money(row.baseSalary)}`,
        amount: row.employeeInsurance || 0,
        always: true,
      }]
      : [
        { label: "BHXH người lao động (8%)", note: `8% × lương đóng BH ${money(row.insuranceContributionBase || row.baseSalary)}`, amount: row.bhxhNV || 0, always: true },
        { label: "BHYT người lao động (1,5%)", note: `1,5% × lương đóng BH ${money(row.insuranceContributionBase || row.baseSalary)}`, amount: row.bhytNV || 0, always: true },
        { label: "BHTN người lao động (1%)", note: `1% × lương đóng BH ${money(row.insuranceContributionBase || row.baseSalary)}`, amount: row.bhtnNV || 0, always: true },
      ];

  const deductionItems = [
    ...employeeInsuranceItems,
    {
      label: usesFlatWithholding ? "Thuế TNCN khấu trừ (10%)" : "Thuế thu nhập cá nhân",
      note: usesFlatWithholding
        ? `Khấu trừ 10% khi mức chi trả từ ${money(row.flatTaxThreshold || taxPolicy.flatTaxThreshold)}/lần`
        : `Thu nhập tính thuế ${money(row.taxableIncome)}${row.personalDeduction > 0 ? ` · giảm trừ gia cảnh ${money(row.personalDeduction)}` : ""}${row.mealTaxFree > 0 ? ` · miễn tiền ăn ${money(row.mealTaxFree)}` : ""}${row.overtimeTaxFree > 0 ? ` · miễn OT ${money(row.overtimeTaxFree)}` : ""}`,
      amount: row.thueTNCN || 0,
      always: true,
    },
    { label: "Tạm ứng / khấu trừ trên hồ sơ", note: "", amount: row.advance || 0 },
  ].filter((item) => item.always || (Number(item.amount) || 0) > 0);

  const grossIncome = Number(row.grossIncome) || 0;
  // Hai ô tổng "Phụ cấp" và "Thưởng" cộng thẳng từ chính các dòng đang liệt kê ngay bên trên
  // (nhóm giống hệt payrollAllowanceTotal/payrollBonusTotal của Bảng lương tổng quát, kể cả
  // tiền tăng ca nằm trong nhóm phụ cấp) — người xem cộng nhẩm là ra đúng số trong ô.
  const sumItems = (items) => items.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  const allowanceSum = sumItems(allowanceItems);
  const bonusSum = sumItems(bonusItems);

  // Phiếu phát cho nhân viên chỉ có ĐÚNG MỘT số tiền cuối cùng: THỰC NHẬN = số tiền chuyển
  // cho nhân sự. Số này lấy nguyên từ bảng lương đang lưu (row.net = thu nhập - BH - thuế -
  // tạm ứng), đúng bằng số mà bước chi trả cưỡng chế chuyển khoản; chứng từ chi trả cũ tuyệt
  // đối không được ghi đè để phiếu không bao giờ hiện hai con số khác nhau.
  const rowNetRaw = row?.net;
  const hasRowNet = rowNetRaw !== undefined && rowNetRaw !== null && rowNetRaw !== ""
    && Number.isFinite(Number(rowNetRaw));
  const netFinal = Math.max(0, Math.round(hasRowNet ? Number(rowNetRaw) : grossIncome - deductionItems.reduce((sum, item) => sum + (Number(item.amount) || 0), 0)));

  // Bảng khấu trừ phải cộng ra đúng THỰC NHẬN. Nếu bảng lương còn khoản trừ nào chưa được
  // liệt kê thành dòng riêng, gộp thành một dòng cân đối thay vì để phiếu tự mâu thuẫn.
  const listedDeduction = deductionItems.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  const balancingDeduction = Math.round(grossIncome - listedDeduction - netFinal);
  if (Math.abs(balancingDeduction) >= 1) {
    deductionItems.push({
      label: balancingDeduction > 0 ? "Khoản trừ khác theo bảng lương" : "Điều chỉnh tăng theo bảng lương",
      note: "Chênh lệch giữa các khoản đã liệt kê và số thực nhận trên bảng lương kỳ này",
      amount: balancingDeduction,
    });
  }
  const totalDeduction = deductionItems.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
  const netSourceLabel = "Tổng thu nhập - Tổng khấu trừ · đúng số tiền chuyển cho nhân viên";

  // Ứng lương giữa tháng đã được chi riêng và KHÔNG trừ vào số thực nhận kỳ này -> chỉ ghi chú,
  // không đưa vào bảng khấu trừ để tổng cộng của phiếu luôn khớp số chuyển khoản.
  const midMonthList = (Array.isArray(midMonthEntries) ? midMonthEntries : [])
    .filter((entry) => (Number(entry?.amount) || 0) > 0);
  const midMonthTotal = midMonthList.reduce((sum, entry) => sum + (Number(entry.amount) || 0), 0);

  const accountantApproved = Boolean(approval?.accountantApprovedAt || approval?.approval_status === "accountant_approved");
  const bossApproved = Boolean(approval?.bossApprovedAt || ["director_approved", "approved"].includes(approval?.approval_status));
  // Bảng THU NHẬP tách thành 3 mục rõ ràng theo chuẩn kế toán: I. Lương · II. Phụ cấp ·
  // III. Thưởng. Mỗi dòng mục mang luôn tổng của mục đó nên đọc là biết ngay cơ cấu thu nhập,
  // các khoản chi tiết đánh số lại từ 1 trong từng mục.
  const keepIncomeItem = (item) => item.always || (Number(item.amount) || 0) > 0
    || String(item.label || "").toLowerCase().includes("chuyên cần");
  const incomeGroups = [
    { code: "I", label: "Lương", items: salaryItems.filter(keepIncomeItem), total: sumItems(salaryItems) },
    { code: "II", label: "Phụ cấp", items: allowanceItems.filter(keepIncomeItem), total: allowanceSum },
    { code: "III", label: "Thưởng", items: bonusItems.filter(keepIncomeItem), total: bonusSum },
  ];
  const incomeItems = incomeGroups.flatMap((group) => [{ group: true }, ...group.items]);
  const beneficiaryName = row.bankAccountHolder || row.name || "";
  const bankName = row.bankName || "Chưa khai báo";
  const bankAccount = row.bankAccount || "Chưa khai báo";
  const paymentMethodLabel = payment?.paymentMethod === "tien_mat" ? "Tiền mặt" : payment?.paymentMethod === "chuyen_khoan" ? "Chuyển khoản" : "Chưa chi trả";
  const maxRows = Math.max(incomeItems.length, deductionItems.length);
  // Ba dòng mục làm bảng thu nhập cao thêm ~3 dòng, nên mốc co gọn hạ xuống tương ứng để
  // phiếu vẫn nằm trọn MỘT trang A4.
  const densityClass = maxRows >= 10 ? "ultra-dense" : maxRows >= 7 ? "dense" : "";

  const renderTableRows = (items, type) => items.map((item, idx) => `
    <tr>
      <td class="idx">${idx + 1}</td>
      <td>
        <div class="entry-label">${payslipEscape(item.label)}</div>
        ${item.note ? `<div class="entry-note">${payslipEscape(item.note)}</div>` : ""}
      </td>
      <td class="amount ${type}">${type === "deduct" && (Number(item.amount) || 0) > 0 ? "-" : (type === "income" && (Number(item.amount) || 0) > 0 ? "+" : "")}${num(item.amount)}</td>
    </tr>`).join("");

  // Bảng thu nhập: dòng mục (I/II/III) + các dòng chi tiết đánh số riêng trong từng mục.
  const renderIncomeRows = () => incomeGroups.map((group) => `
    <tr class="group-row">
      <td class="idx">${group.code}</td>
      <td><div class="group-label">${payslipEscape(group.label)}</div></td>
      <td class="amount income">${num(group.total)}</td>
    </tr>
    ${group.items.map((item, idx) => `
    <tr>
      <td class="idx">${idx + 1}</td>
      <td>
        <div class="entry-label">${payslipEscape(item.label)}</div>
        ${item.note ? `<div class="entry-note">${payslipEscape(item.note)}</div>` : ""}
      </td>
      <td class="amount income">${(Number(item.amount) || 0) > 0 ? "+" : ""}${num(item.amount)}</td>
    </tr>`).join("")}`).join("");

  const css = `${PAYSLIP_BASE_CSS}
    /* Toàn phiếu dùng Times New Roman (VnTime) theo chuẩn văn bản hành chính Việt Nam. */
    .payslip-root { width: 794px; padding: 6px 15px 8px; font-family: "Times New Roman", "Nimbus Roman No9 L", "Liberation Serif", Times, serif; color: #10233f; font-size: 10.6px; line-height: 1.4; }
    /* KHÔNG đặt page-break-inside: avoid cho cả phiếu — html2pdf sẽ đẩy nguyên khối cao gần
       bằng trang sang trang sau, sinh ra một trang trắng ở đầu. Chỉ khối chữ ký mới cần avoid. */
    .payslip-root .employee-slip { width: 100%; }
    .payslip-root .slip-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 18px; }
    .payslip-root .brand-block { width: 60%; }
    .payslip-root .brand-logo { font-size: 30px; line-height: .95; font-weight: 700; color: #0c3d91; letter-spacing: .8px; }
    .payslip-root .company-name { margin-top: 4px; font-size: 11.6px; font-weight: 700; color: #1e293b; text-transform: uppercase; }
    .payslip-root .company-line { margin-top: 5px; font-size: 9.6px; color: #475569; line-height: 1.45; }
    .payslip-root .title-block { margin-top: 4px; text-align: center; }
    .payslip-root .slip-title { margin: 0; font-size: 23px; font-weight: 700; color: #123f93; letter-spacing: .4px; text-align: center; }
    .payslip-root .period-pill { display: inline-flex; align-items: center; justify-content: center; margin-top: 8px; min-height: 26px; background: #0c3d91; color: #fff; border-radius: 8px; padding: 6px 22px; font-weight: 700; font-size: 10.6px; line-height: 1.4; letter-spacing: .3px; text-align: center; }
    .payslip-root .slip-meta { width: 40%; text-align: right; color: #334155; font-size: 9.6px; line-height: 1.6; }
    .payslip-root .slip-meta b { color: #0f172a; }
    .payslip-root .period-note { margin-top: 8px; border: 1px solid #edd184; background: #fff9e9; color: #8a6513; border-radius: 7px; padding: 5px 8px; font-size: 8px; font-weight: 700; line-height: 1.35; }

    .payslip-root .employee-info { margin-top: 9px; display: grid; grid-template-columns: 1.08fr 1.2fr .72fr .86fr; border: 1px solid #d8e0ec; border-radius: 12px; overflow: hidden; }
    /* Mọi ô đều canh GIỮA theo chiều dọc, chữ không dính vào đường kẻ. */
    .payslip-root .info-box { padding: 9px 10px; min-height: 58px; border-right: 1px solid #e2e8f0; background: #fff; display: flex; flex-direction: column; justify-content: center; }
    .payslip-root .info-box:last-child { border-right: none; }
    .payslip-root .info-label { font-size: 9.2px; text-transform: uppercase; color: #64748b; font-weight: 700; letter-spacing: .35px; line-height: 1.3; }
    .payslip-root .info-value { margin-top: 5px; color: #0f172a; font-size: 12px; line-height: 1.4; font-weight: 700; }

    .payslip-root .money-tables { margin-top: 11px; display: grid; grid-template-columns: 1fr 1fr; gap: 10px; align-items: start; }
    .payslip-root .money-panel { border: 1px solid #d8e0ec; border-radius: 12px; overflow: hidden; background: #fff; }
    .payslip-root .money-head { display: flex; align-items: center; gap: 7px; background: #0b3d91; color: #fff; padding: 7px 10px; font-size: 11.6px; font-weight: 700; text-transform: uppercase; }
    .payslip-root .money-icon { width: 20px; height: 20px; border-radius: 50%; background: #fff; color: #0b3d91; display: inline-flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; }
    .payslip-root table.emp-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
    .payslip-root .emp-table th, .payslip-root .emp-table td { border: 1px solid #e3e8f1; padding: 8.4px 9px; vertical-align: middle; }
    .payslip-root .emp-table thead th { background: #f7f9fc; color: #475569; font-size: 9.4px; font-weight: 700; text-transform: uppercase; padding: 8px 9px; line-height: 1.3; }
    .payslip-root .emp-table .idx { width: 32px; text-align: center; color: #475569; }
    .payslip-root .emp-table .amount { width: 108px; text-align: right; white-space: nowrap; font-size: 11.6px; font-weight: 700; }
    .payslip-root .emp-table .amount.income { color: #047857; }
    .payslip-root .emp-table .amount.deduct { color: #c62828; }
    .payslip-root .entry-label { font-size: 11.2px; font-weight: 700; color: #0f172a; line-height: 1.42; }
    .payslip-root .entry-note { margin-top: 3px; color: #5b6b80; font-size: 9.6px; line-height: 1.5; }
    /* Dòng MỤC của bảng thu nhập (I. Lương · II. Phụ cấp · III. Thưởng) — mảnh, nền nhạt. */
    .payslip-root .emp-table .group-row td { background: #f2f6fc; padding: 4.6px 9px; }
    .payslip-root .emp-table .group-row .idx { color: #0b3d91; font-weight: 700; }
    .payslip-root .emp-table .group-row .amount { color: #0b3d91; font-size: 11px; }
    .payslip-root .group-label { font-size: 10.4px; font-weight: 700; color: #0b3d91; text-transform: uppercase; letter-spacing: .3px; line-height: 1.3; }
    /* Dòng tổng của mỗi bảng: nền nhạt đậm hơn + kẻ trên rõ để nổi khỏi các dòng chi tiết. */
    .payslip-root .emp-total td { background: #e9f0fa; border-top: 1.6px solid #b9cce8; font-size: 11.6px; font-weight: 700; text-transform: uppercase; padding: 8.5px 9px; color: #0b3d91; }

    .payslip-root .net-banner { margin-top: 9px; min-height: 54px; border-radius: 12px; background: linear-gradient(90deg,#0b3d91,#08479d); color: #fff; display: flex; align-items: center; justify-content: space-between; padding: 10px 15px; }
    .payslip-root .net-label { font-size: 13.2px; font-weight: 700; text-transform: uppercase; letter-spacing: .3px; }
    .payslip-root .net-formula { margin-top: 3px; font-size: 9.6px; opacity: .95; }
    .payslip-root .net-money { font-size: 30px; line-height: 1; font-weight: 700; letter-spacing: .4px; white-space: nowrap; }
    .payslip-root .words-line { margin-top: 7px; font-size: 10.4px; color: #334155; line-height: 1.4; }

    /* 6 ô tóm tắt: lương cơ bản · phụ cấp · thưởng · tổng thu nhập · tổng khấu trừ · thực nhận. */
    .payslip-root .quick-summary { margin-top: 7px; display: grid; grid-template-columns: repeat(6,1fr); border: 1px solid #d8e0ec; border-radius: 10px; overflow: hidden; background: #f9fbfe; }
    .payslip-root .quick-cell { padding: 8px 6px; min-height: 45px; text-align: center; border-right: 1px solid #e2e8f0; display: flex; flex-direction: column; justify-content: center; }
    .payslip-root .quick-cell:last-child { border-right: none; }
    .payslip-root .quick-label { font-size: 8.4px; color: #64748b; text-transform: uppercase; font-weight: 700; line-height: 1.3; }
    .payslip-root .quick-value { margin-top: 4px; font-size: 10.8px; font-weight: 700; color: #10233f; line-height: 1.35; white-space: nowrap; }
    .payslip-root .quick-value.allowance { color: #92610a; }
    .payslip-root .quick-value.bonus { color: #047857; }
    .payslip-root .quick-value.takehome { color: #0b3d91; font-size: 11.8px; }

    .payslip-root .bank-strip { margin-top: 7px; border: 1px solid #d8e0ec; border-radius: 10px; overflow: hidden; }
    .payslip-root .bank-title { padding: 6px 10px; background: #f4f7fb; color: #0b3d91; font-size: 9.8px; font-weight: 700; text-transform: uppercase; border-bottom: 1px solid #e2e8f0; }
    .payslip-root .bank-grid { display: grid; grid-template-columns: .95fr 1fr 1.05fr 1.05fr; }
    .payslip-root .bank-item { padding: 8px 9px; min-height: 49px; border-right: 1px solid #e2e8f0; display: flex; flex-direction: column; justify-content: center; }
    .payslip-root .bank-item:last-child { border-right: none; }
    .payslip-root .bank-label { font-size: 8.6px; text-transform: uppercase; color: #64748b; font-weight: 700; line-height: 1.3; }
    .payslip-root .bank-value { margin-top: 4px; font-size: 10.6px; line-height: 1.4; color: #0f172a; font-weight: 700; word-break: break-word; }
    .payslip-root .bank-method { margin-top: 3px; font-size: 8.8px; font-weight: 400; color: #64748b; line-height: 1.3; }
    .payslip-root .bank-amount { margin-top: 1px; font-size: 12.4px; font-weight: 700; color: #0b3d91; line-height: 1.3; white-space: nowrap; }
    .payslip-root .reconcile-note { margin-top: 5px; border-radius: 7px; padding: 4px 7px; background: #fff6e8; border: 1px solid #f2d5a5; color: #9a6700; font-size: 8.5px; line-height: 1.3; }

    .payslip-root .signature-block { margin-top: 9px; border-top: 1px solid #e2e8f0; padding-top: 7px; page-break-inside: avoid; }
    .payslip-root .sign-date { text-align: right; color: #64748b; font-size: 9.4px; font-style: italic; margin: 0; }
    .payslip-root .sign-grid { margin-top: 8px; display: grid; grid-template-columns: repeat(3,1fr); gap: 10px; }
    .payslip-root .sign-cell { text-align: center; min-height: 94px; }
    .payslip-root .sign-role { font-size: 10.6px; font-weight: 700; text-transform: uppercase; color: #10233f; }
    .payslip-root .sign-hint { margin-top: 2px; font-size: 8.8px; color: #64748b; font-style: italic; }
    .payslip-root .sign-space { height: 42px; }
    .payslip-root .sign-who { margin-top: 6px; font-size: 10.6px; font-weight: 700; color: #1f2937; }
    .payslip-root .sign-when { margin-top: 2px; font-size: 8.6px; color: #64748b; }
    .payslip-root .ok { color: #166534; border: 1.7px solid #16a34a; display: inline-block; border-radius: 6px; padding: 3px 10px; margin-top: 9px; font-size: 9px; font-weight: 700; transform: rotate(-5deg); }
    .payslip-root .pending { margin-top: 13px; color: #64748b; font-size: 8.5px; font-style: italic; }
    .payslip-root .stamp { width: 66px; height: 66px; border: 1.8px double #c62828; border-radius: 50%; color: #c62828; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; padding: 5px; margin: 4px auto 0; transform: rotate(-9deg); }
    .payslip-root .stamp .s1 { font-size: 8.2px; font-weight: 700; line-height: 1.18; }
    .payslip-root .stamp .s2 { margin-top: 1px; font-size: 5px; font-weight: 700; text-transform: uppercase; line-height: 1.15; }
    .payslip-root .stamp .s3 { margin-top: 1px; font-size: 4.9px; line-height: 1.15; }
    .payslip-root .stamp.empty { border-style: dashed; color: #94a3b8; transform: none; }
    .payslip-root .employee-foot { margin-top: 8px; border-top: 1px solid #e2e8f0; padding-top: 6px; color: #64748b; font-size: 9px; line-height: 1.4; text-align: center; }

    /* Nhân viên nhiều khoản: co dần để giữ đúng MỘT trang A4 mà chữ vẫn đọc được. */
    .payslip-root .employee-slip.dense .emp-table th, .payslip-root .employee-slip.dense .emp-table td { padding: 7px 8px; }
    .payslip-root .employee-slip.dense .emp-table .group-row td { padding: 3.8px 8px; }
    .payslip-root .employee-slip.dense .group-label { font-size: 10px; }
    .payslip-root .employee-slip.dense .entry-label { font-size: 10.4px; }
    .payslip-root .employee-slip.dense .entry-note { font-size: 9px; line-height: 1.4; }
    .payslip-root .employee-slip.dense .info-box { min-height: 56px; padding: 8px 9px; }
    .payslip-root .employee-slip.dense .quick-cell { min-height: 44px; padding: 7px; }
    .payslip-root .employee-slip.dense .bank-item { min-height: 48px; padding: 7px 8px; }
    .payslip-root .employee-slip.dense .net-banner { min-height: 52px; padding: 8px 14px; }
    .payslip-root .employee-slip.dense .net-money { font-size: 27px; }
    .payslip-root .employee-slip.dense .sign-space { height: 40px; }
    .payslip-root .employee-slip.dense .sign-cell { min-height: 92px; }

    .payslip-root .employee-slip.ultra-dense .emp-table th, .payslip-root .employee-slip.ultra-dense .emp-table td { padding: 2.4px 7px; }
    .payslip-root .employee-slip.ultra-dense .emp-table thead th { padding: 5px 7px; }
    .payslip-root .employee-slip.ultra-dense .emp-table .group-row td { padding: 2.2px 7px; }
    .payslip-root .employee-slip.ultra-dense .group-label { font-size: 9.4px; }
    .payslip-root .employee-slip.ultra-dense .emp-table .group-row .amount { font-size: 10px; }
    .payslip-root .employee-slip.ultra-dense .emp-total td { padding: 4.5px 7px; font-size: 10.4px; }
    .payslip-root .employee-slip.ultra-dense .entry-label { font-size: 9.8px; line-height: 1.32; }
    .payslip-root .employee-slip.ultra-dense .entry-note { font-size: 8.4px; line-height: 1.26; margin-top: 1.5px; }
    .payslip-root .employee-slip.ultra-dense .money-head { padding: 5px 9px; font-size: 10.6px; }
    .payslip-root .employee-slip.ultra-dense .money-tables { margin-top: 6px; }
    .payslip-root .employee-slip.ultra-dense .info-box { min-height: 38px; padding: 3px 9px; }
    .payslip-root .employee-slip.ultra-dense .info-value { font-size: 10.8px; margin-top: 3px; }
    .payslip-root .employee-slip.ultra-dense .employee-info { margin-top: 7px; }
    .payslip-root .employee-slip.ultra-dense .quick-cell { min-height: 31px; padding: 2.5px 6px; }
    .payslip-root .employee-slip.ultra-dense .quick-value { font-size: 10.6px; margin-top: 2px; }
    .payslip-root .employee-slip.ultra-dense .quick-summary { margin-top: 6px; }
    .payslip-root .employee-slip.ultra-dense .bank-item { min-height: 34px; padding: 2.5px 8px; }
    .payslip-root .employee-slip.ultra-dense .bank-title { padding: 4px 10px; }
    .payslip-root .employee-slip.ultra-dense .bank-strip { margin-top: 6px; }
    .payslip-root .employee-slip.ultra-dense .bank-amount { font-size: 11.4px; }
    .payslip-root .employee-slip.ultra-dense .net-banner { margin-top: 5px; min-height: 39px; padding: 4px 13px; }
    .payslip-root .employee-slip.ultra-dense .net-money { font-size: 23px; }
    .payslip-root .employee-slip.ultra-dense .net-label { font-size: 12px; }
    .payslip-root .employee-slip.ultra-dense .words-line { margin-top: 4px; font-size: 9.4px; }
    .payslip-root .employee-slip.ultra-dense .signature-block { margin-top: 6px; padding-top: 5px; }
    .payslip-root .employee-slip.ultra-dense .sign-grid { margin-top: 5px; }
    .payslip-root .employee-slip.ultra-dense .sign-space { height: 14px; }
    .payslip-root .employee-slip.ultra-dense .sign-cell { min-height: 50px; }
    .payslip-root .employee-slip.ultra-dense .employee-foot { margin-top: 5px; padding-top: 4px; font-size: 8.4px; }
  `;

  const body = `
<div class="employee-slip ${densityClass}">
  <div class="slip-header">
    <div class="brand-block">
      <div class="brand-logo">DOMIX</div>
      <div class="company-name">${payslipEscape(companyName)}</div>
      ${companyAddress ? `<div class="company-line">${payslipEscape(companyAddress)}</div>` : ""}
      ${(companyPhone || companyTaxCode) ? `<div class="company-line">${companyPhone ? `ĐT: ${payslipEscape(companyPhone)}` : ""}${companyPhone && companyTaxCode ? " · " : ""}${companyTaxCode ? `MST: ${payslipEscape(companyTaxCode)}` : ""}</div>` : ""}
    </div>
    <div class="slip-meta">
      <div>Số phiếu: <b>${payslipEscape(slipCode)}</b></div>
      <div>Ngày lập: <b>${createdDate}</b></div>
      ${statusLabel ? `<div>Trạng thái: <b>${payslipEscape(statusLabel)}</b></div>` : ""}
    </div>
  </div>

  <div class="title-block">
    <h1 class="slip-title">PHIẾU LƯƠNG NHÂN VIÊN</h1>
    <div class="period-pill">KỲ LƯƠNG THÁNG ${String(month).padStart(2, "0")}/${year}</div>
  </div>

  <div class="employee-info">
    <div class="info-box"><div class="info-label">Nhân viên</div><div class="info-value">${payslipEscape(row.name)}</div></div>
    <div class="info-box"><div class="info-label">Chức vụ / bộ phận</div><div class="info-value">${payslipEscape(row.position || "Chưa khai báo")}${row.department ? `<br>${payslipEscape(row.department)}` : ""}</div></div>
    <div class="info-box"><div class="info-label">Ngày công</div><div class="info-value">${Number(row.actualDays || 0).toFixed(1)} / ${row.standardDays}</div></div>
    <div class="info-box"><div class="info-label">Lương cơ bản</div><div class="info-value">${money(row.baseSalary)}</div></div>
  </div>

  <div class="money-tables">
    <div class="money-panel">
      <div class="money-head"><span class="money-icon">↑</span> Thu nhập</div>
      <table class="emp-table">
        <thead><tr><th class="idx">STT</th><th>Khoản thu nhập</th><th class="amount">Số tiền (đ)</th></tr></thead>
        <tbody>
          ${renderIncomeRows()}
          <tr class="emp-total"><td colspan="2">Tổng thu nhập</td><td class="amount income">${num(grossIncome)}</td></tr>
        </tbody>
      </table>
    </div>
    <div class="money-panel">
      <div class="money-head"><span class="money-icon">↓</span> Khấu trừ</div>
      <table class="emp-table">
        <thead><tr><th class="idx">STT</th><th>Khoản khấu trừ</th><th class="amount">Số tiền (đ)</th></tr></thead>
        <tbody>
          ${renderTableRows(deductionItems, "deduct")}
          <tr class="emp-total"><td colspan="2">Tổng khấu trừ</td><td class="amount deduct">${num(totalDeduction)}</td></tr>
        </tbody>
      </table>
    </div>
  </div>

  <div class="net-banner">
    <div><div class="net-label">Thực nhận</div><div class="net-formula">${payslipEscape(netSourceLabel)}</div></div>
    <div class="net-money">${money(netFinal)}</div>
  </div>
  <div class="words-line">Bằng chữ: <b>${payslipEscape(vndInWords(netFinal))}</b>.</div>

  <div class="quick-summary">
    <div class="quick-cell"><div class="quick-label">Lương cơ bản</div><div class="quick-value">${money(row.baseSalary)}</div></div>
    <div class="quick-cell"><div class="quick-label">Tổng phụ cấp</div><div class="quick-value allowance">${money(allowanceSum)}</div></div>
    <div class="quick-cell"><div class="quick-label">Tổng thưởng</div><div class="quick-value bonus">${money(bonusSum)}</div></div>
    <div class="quick-cell"><div class="quick-label">Tổng thu nhập</div><div class="quick-value">${money(grossIncome)}</div></div>
    <div class="quick-cell"><div class="quick-label">Tổng khấu trừ</div><div class="quick-value">${money(totalDeduction)}</div></div>
    <div class="quick-cell"><div class="quick-label">Thực nhận</div><div class="quick-value takehome">${money(netFinal)}</div></div>
  </div>

  <div class="bank-strip">
    <div class="bank-title">Thông tin tài khoản thụ hưởng</div>
    <div class="bank-grid">
      <div class="bank-item"><div class="bank-label">Ngân hàng</div><div class="bank-value">${payslipEscape(bankName)}</div></div>
      <div class="bank-item"><div class="bank-label">Số tài khoản</div><div class="bank-value">${payslipEscape(bankAccount)}</div></div>
      <div class="bank-item"><div class="bank-label">Người thụ hưởng</div><div class="bank-value">${payslipEscape(beneficiaryName)}</div></div>
      <div class="bank-item"><div class="bank-label">Số tiền chuyển thực tế</div><div class="bank-method">${payslipEscape(paymentMethodLabel)}</div><div class="bank-amount">${money(netFinal)}</div></div>
    </div>
  </div>
  ${midMonthTotal > 0 ? `<div class="reconcile-note">Đã ứng lương giữa tháng ${money(midMonthTotal)} (${midMonthList.map((entry) => `${dmy(entry.date)} ${money(entry.amount)}`).join(" · ")}) — khoản này đã chi riêng trước đó, không trừ vào số thực nhận kỳ này.</div>` : ""}
  <div class="signature-block">
    <div class="sign-date">Ngày ${new Date().getDate()} tháng ${new Date().getMonth() + 1} năm ${new Date().getFullYear()}</div>
    <div class="sign-grid">
      <div class="sign-cell">
        <div class="sign-role">Người lao động</div><div class="sign-hint">(Ký, ghi rõ họ tên)</div>
        <div class="sign-space"></div><div class="sign-who">${payslipEscape(row.name)}</div>
      </div>
      <div class="sign-cell">
        <div class="sign-role">Kế toán duyệt</div><div class="sign-hint">(Ký, ghi rõ họ tên)</div>
        ${accountantApproved ? `<div class="ok">ĐÃ DUYỆT</div><div class="sign-who">${payslipEscape(approval.accountantApprovedByName || approval.accountantApprovedByEmail || "Kế toán")}</div><div class="sign-when">${payslipEscape(approval.accountantApprovedAt || "")}</div>` : `<div class="pending">Chưa duyệt</div>`}
      </div>
      <div class="sign-cell">
        <div class="sign-role">Giám đốc duyệt</div><div class="sign-hint">(Ký tên, đóng dấu)</div>
        ${bossApproved ? `<div class="stamp"><div class="s1">ĐÃ DUYỆT</div><div class="s2">${payslipEscape(companyName)}</div><div class="s3">${payslipEscape(approval.bossApprovedAt || "")}</div></div><div class="sign-who">${payslipEscape(approval.bossApprovedByName || approval.bossApprovedByEmail || "Giám đốc")}</div>` : `<div class="stamp empty"><div class="s1">CHƯA<br>ĐÓNG DẤU</div></div>`}
      </div>
    </div>
    <div class="employee-foot">Phiếu lương được lập tự động từ hệ thống DOMIX. Thực nhận = Tổng thu nhập - Tổng khấu trừ.</div>
  </div>
</div>`;

  return { css, body, month, year };
}

// Bản HTML đầy đủ — chỉ dùng làm DỰ PHÒNG khi không tạo được PDF trực tiếp (mở lên là tự bật hộp thoại in).
function buildPayslipHtml(row, options = {}) {
  const { css, body, month, year } = buildPayslipParts(row, options);
  const autoPrint = "<scr" + "ipt>window.addEventListener('load', function () { setTimeout(function () { window.print(); }, 350); });</scr" + "ipt>";
  return `<!DOCTYPE html><html lang="vi"><head><meta charset="utf-8">
<title>Phieu luong T${month}-${year} - ${payslipEscape(row.name)}</title>
<style>@page { size: A4; margin: 12mm; } body { margin: 0; } @media print { .payslip-root { padding: 0; } }${css}</style></head>
<body><div class="payslip-root">${body}</div>${autoPrint}</body></html>`;
}

const payslipFileBase = (row, period = {}) =>
  `DOMIX_Phieu_luong_T${period.month || ATT_MONTH}-${period.year || ATT_YEAR}_${String(row.name || "nhan_vien").trim().replace(/\s+/g, "_")}`;

// Xuất TRỰC TIẾP file .pdf phiếu lương của MỘT nhân viên — không cần qua hộp thoại in.
async function exportPayslipPdf(row, options = {}) {
  const { css, body } = buildPayslipParts(row, options);
  await saveA4Pdf({
    css,
    body,
    filename: payslipFileBase(row, options.period),
    fallbackHtml: buildPayslipHtml(row, options),
  });
}

// Xuất PDF BẢNG KÊ BẢO HIỂM cả kỳ (tab Bảo hiểm của Bảng lương): mỗi nhân viên một dòng,
// tách phần NHÂN VIÊN đóng / DOANH NGHIỆP đóng, có tổng cộng và khối ký duyệt.
async function exportInsurancePdf(payrollRows, { company = {}, period = {} } = {}) {
  const month = Number(period.month) || ATT_MONTH;
  const year = Number(period.year) || ATT_YEAR;
  const money = (n) => `${Math.round(Number(n) || 0).toLocaleString("vi-VN")}đ`;
  const companyName = company?.name || "CÔNG TY DOMIX";
  const totalNV = payrollRows.reduce((s, r) => s + (Number(r.employeeInsurance) || 0), 0);
  const totalDN = payrollRows.reduce((s, r) => s + (Number(r.employerInsurance) || 0), 0);
  const rowsHtml = payrollRows.map((r, index) => `
    <tr>
      <td class="c">${index + 1}</td>
      <td>${payslipEscape(r.name)}<div class="note">${payslipEscape(r.position || ROLE_META[r.roleType]?.label || "Nhân viên")} · ${payslipEscape(r.contractLabel || "—")} · công ${Number(r.actualDays || 0).toFixed(1)}/${r.standardDays}</div></td>
      <td>${r.insuranceFixed ? "Số tiền cố định" : "% theo luật"}${r.insuranceSuspendedForUnpaidLeave ? `<div class="note">${Number(r.unpaidLeaveDays || 0)} ngày không hưởng lương — tạm dừng đóng BH kỳ này</div>` : `<div class="note">Không suy theo số công thực tế; xét ngày không hưởng lương</div>`}</td>
      <td class="r mono">${money(r.insuranceContributionBase || r.baseSalary)}</td>
      <td class="r mono">${money(r.employeeInsurance)}${!r.insuranceFixed && (Number(r.employeeInsurance) || 0) > 0 ? `<div class="note">BHXH ${money(r.bhxhNV)} · BHYT ${money(r.bhytNV)} · BHTN ${money(r.bhtnNV)}</div>` : ""}</td>
      <td class="r mono">${money(r.employerInsurance)}${!r.insuranceFixed && (Number(r.employerInsurance) || 0) > 0 ? `<div class="note">BHXH 17 · BHYT 3 · BHTN 1 · TNLĐ 0,5 (%)</div>` : ""}</td>
      <td class="r mono">${money((Number(r.employeeInsurance) || 0) + (Number(r.employerInsurance) || 0))}</td>
    </tr>`).join("");
  const body = `
<div class="co">
  <div>
    <b>${payslipEscape(companyName)}</b><br>
    ${payslipEscape(company?.address || "")}<br>
    ${company?.taxCode ? `MST: ${payslipEscape(company.taxCode)}` : ""}
  </div>
  <div style="text-align:right">Kỳ: <b>tháng ${month}/${year}</b><br>Số nhân sự: <b>${payrollRows.length}</b></div>
</div>
<h1>BẢNG KÊ BẢO HIỂM XÃ HỘI</h1>
<p class="sub">BHXH · BHYT · BHTN · BH TNLĐ-BNN — kỳ tháng ${month} năm ${year}</p>
<table class="grid">
  <tr><th class="c">STT</th><th>Nhân viên</th><th>Cơ chế</th><th class="r">Lương đóng BH</th><th class="r">NV đóng (10,5%)</th><th class="r">DN đóng (21,5%)</th><th class="r">Tổng nộp</th></tr>
  ${rowsHtml || `<tr><td class="c">—</td><td colspan="6">Không có nhân sự trong kỳ này.</td></tr>`}
  <tr class="total"><td></td><td colspan="3">TỔNG CỘNG</td><td class="r mono">${money(totalNV)}</td><td class="r mono">${money(totalDN)}</td><td class="r mono">${money(totalNV + totalDN)}</td></tr>
</table>
<p class="note" style="margin-top:8px">Phần NV đóng trừ vào thực lĩnh; phần DN đóng là chi phí doanh nghiệp. Không dùng quy tắc “đủ 14 ngày công mới đóng”. Trường hợp thuộc diện BH bắt buộc chỉ tạm dừng đóng tháng đó khi người lao động không hưởng tiền lương từ đủ 14 ngày làm việc trở lên trong tháng.</p>
<table class="sign">
  <tr>
    <td style="width:50%">
      <div class="role">Người lập biểu (Kế toán)</div>
      <div class="hint">(Ký, ghi rõ họ tên)</div>
      <div style="height:70px"></div>
    </td>
    <td style="width:50%">
      <div class="role">Giám đốc</div>
      <div class="hint">(Ký tên, đóng dấu)</div>
      <div style="height:70px"></div>
    </td>
  </tr>
</table>
<div class="foot">Bảng kê được lập tự động từ hệ thống quản trị ${payslipEscape(companyName)} ngày ${new Date().toISOString().slice(0, 10).split("-").reverse().join("/")}.</div>`;
  await saveA4Pdf({ body, filename: `DOMIX_Bao_hiem_T${month}-${year}` });
}

// Nút PDF tại bảng Nhân sự dùng chung đúng một mẫu phiếu lương chi tiết. Việc dùng lại
// buildPayslipParts bảo đảm tên và số tiền của từng phụ cấp không bị gộp thành một ô tổng.
async function exportEmployeeProfilePdf(employee, { company = {}, pay = {}, period = {}, cong = 0, standardDays = 26, approval = null, payment = null } = {}) {
  const month = Number(period.month) || ATT_MONTH;
  const year = Number(period.year) || ATT_YEAR;
  const row = {
    ...employee,
    ...pay,
    id: employee.id ?? pay.id,
    name: employee.name || pay.name,
    actualDays: Number(pay.actualDays ?? cong) || 0,
    standardDays: Number(pay.standardDays ?? standardDays) || 26,
    bankName: employee.bankName || pay.bankName || "",
    bankAccount: employee.bankAccount || pay.bankAccount || "",
    bankAccountHolder: employee.bankAccountHolder || pay.bankAccountHolder || employee.name || pay.name || "",
  };
  const options = {
    company,
    period: { month, year },
    approval,
    payment,
    statusLabel: payment ? "Đã chi trả" : approval?.bossApprovedAt ? "Đã duyệt - chờ chi trả" : "Chờ duyệt",
  };
  const { css, body } = buildPayslipParts(row, options);
  await saveA4Pdf({
    css,
    body,
    filename: `DOMIX_Luong_bao_hiem_${String(employee.name || "nhan_vien").trim().replace(/\s+/g, "_")}`,
  });
}

// ---------- Small components ----------
function StampBadge({ text, gold, muted }) {
  return (
    <span className={`stamp-ring ${gold ? "gold" : ""} ${muted ? "muted" : ""}`}>
      {gold ? <CheckCircle2 size={11} /> : muted ? <Clock size={11} /> : <AlertTriangle size={11} />}
      {text}
    </span>
  );
}
function LinkChip({ children }) {
  return (
    <span className="ktns-link-chip">
      <Link2 size={9} /> {children}
    </span>
  );
}
// Bấm vào tên hoặc icon bút chì để sửa — dùng khi lỡ gõ sai tên nhân viên.
function EditableName({ value, onSave, className }) {
  const [editing, setEditing] = useState(false);
  const [val, setVal] = useState(value);
  const commit = () => {
    const trimmed = val.trim();
    onSave(trimmed || value);
    setEditing(false);
  };
  if (editing) {
    return (
      <input
        autoFocus
        value={val}
        onChange={(e) => setVal(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => { if (e.key === "Enter") commit(); if (e.key === "Escape") { setVal(value); setEditing(false); } }}
        onClick={(e) => e.stopPropagation()}
        className={`border border-paper-line rounded px-1.5 py-0.5 ${className || ""}`}
      />
    );
  }
  return (
    <span
      className={`inline-flex items-center gap-1 cursor-pointer group ${className || ""}`}
      onClick={(e) => { e.stopPropagation(); setVal(value); setEditing(true); }}
      title="Bấm để sửa tên"
    >
      {value}
      <Pencil size={11} className="text-muted opacity-40 group-hover:opacity-100 shrink-0" />
    </span>
  );
}
// Bộ chọn kỳ dùng chung — thay cho nút bật/tắt 2 trạng thái cũ (cả tháng ↔ toàn bộ lịch sử), giờ
// có thêm lựa chọn "Tuỳ chỉnh: từ ngày X đến ngày Y" — không bắt xem nguyên cả tháng nữa.
function RangeModePicker({ rangeMode, setRangeMode, rangeFrom, setRangeFrom, rangeTo, setRangeTo, reportMonth, reportYear, show, setShow }) {
  const label = rangeMode === "month" ? `Đang xem kỳ ${reportMonth}/${reportYear}` : rangeMode === "custom" ? `${rangeFrom.split("-").reverse().join("/")} → ${rangeTo.split("-").reverse().join("/")}` : "Đang xem toàn bộ lịch sử";
  return (
    <div className="relative">
      <button onClick={() => setShow((v) => !v)} className={`text-xs px-2.5 py-1.5 rounded-md border flex items-center gap-1.5 ${rangeMode !== "all" ? "bg-ink text-white border-ink" : "border-paper-line text-ink-light"}`}>
        <CalendarCheck size={12} /> {label} <ChevronRight size={11} className={`transition-transform ${show ? "rotate-90" : ""}`} />
      </button>
      {show && (
        <div className="absolute left-0 top-full z-[80] mt-1 w-[min(26rem,calc(100vw-2rem))] max-w-[calc(100vw-2rem)] rounded-md border border-paper-line bg-white p-3 shadow-xl">
          <button onClick={() => { setRangeMode("month"); setShow(false); }} className={`w-full text-left text-xs px-2 py-1.5 rounded ${rangeMode === "month" ? "bg-paper font-medium" : "hover:bg-paper"}`}>Cả tháng {reportMonth}/{reportYear}</button>
          <button onClick={() => { setRangeMode("all"); setShow(false); }} className={`w-full text-left text-xs px-2 py-1.5 rounded ${rangeMode === "all" ? "bg-paper font-medium" : "hover:bg-paper"}`}>Toàn bộ lịch sử</button>
          <div className={`px-2 py-1.5 rounded ${rangeMode === "custom" ? "bg-paper" : ""}`}>
            <button onClick={() => setRangeMode("custom")} className={`text-xs mb-2 ${rangeMode === "custom" ? "font-medium" : ""}`}>Tuỳ chỉnh khoảng ngày</button>
            <div className="grid grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-2">
              <input type="date" value={rangeFrom} onChange={(e) => { setRangeFrom(e.target.value); setRangeMode("custom"); }} className="min-w-0 w-full border border-paper-line rounded px-2 py-1.5 text-xs" />
              <span className="text-muted text-[10px]">→</span>
              <input type="date" value={rangeTo} onChange={(e) => { setRangeTo(e.target.value); setRangeMode("custom"); }} className="min-w-0 w-full border border-paper-line rounded px-2 py-1.5 text-xs" />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
// Dòng thống kê gọn MỘT hàng — thay cho các dãy thẻ to choán màn hình; bảng dữ liệu là nhân vật
// chính của trang, số liệu tổng chỉ cần lướt qua được.
function InlineStats({ items, dark, compact }) {
  const rendered = (items || []).filter(Boolean);
  if (rendered.length === 0) return null;
  return (
    <div className={`ktns-menu-rail flex shrink-0 items-center gap-3 overflow-x-auto rounded-lg border px-3 ${compact ? "py-1.5" : "py-2"} ${dark ? "border-white/10 bg-white/5" : "border-paper-line bg-white"}`}>
      {rendered.map((item, index) => (
        <React.Fragment key={item.label}>
          {index > 0 && <span className={`h-4 w-px shrink-0 ${dark ? "bg-white/10" : "bg-paper-line"}`} />}
          {/* compact: chữ giải thích chuyển vào tooltip — dữ liệu là trung tâm, không phải chú thích. */}
          <span
            className={`flex shrink-0 items-center gap-1.5 whitespace-nowrap text-xs ${compact && item.sub ? "cursor-help" : ""}`}
            title={compact && item.sub ? `${item.label}: ${item.sub}` : undefined}
          >
            <span className={`${dark ? "text-[#8fa4c8]" : "text-muted"} ${compact && item.sub ? "underline decoration-dotted underline-offset-2" : ""}`}>{item.label}</span>
            <strong className={`ktns-mono text-sm ${item.className || (dark ? "text-white" : "text-ink")}`}>{item.value}</strong>
            {!compact && item.sub && <span className={`text-[10px] ${dark ? "text-[#7d90b3]" : "text-muted"}`}>{item.sub}</span>}
          </span>
        </React.Fragment>
      ))}
    </div>
  );
}

